using ModelContextProtocol.Server;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithTools<MyTools>()
    .WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

[McpServerToolType]
public static class MyTools
{
    [McpServerTool, Description("Gets the current server time in UTC")]
    public static string GetServerTime() =>
        DateTime.UtcNow.ToString("o");

    [McpServerTool, Description("Echoes back the provided message")]
    public static string Echo(string message) =>
        $"Echo: {message}";
}

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings",
        Name = "AppSettings",
        Description = "Returns application configuration data")]
    public static string GetAppSettings() =>
        """
        {
          "environment": "production",
          "version": "1.0.0",
          "features": {
            "darkMode": true,
            "notifications": true
          },
          "maxRetries": 3,
          "timeoutSeconds": 30
        }
        """;
}

